code_examples.code:
/* fixed */
.a { display: grid; grid-template-rows: 100px 200px; grid-template-columns: 400px 800px; }
/* shorthand: rows / columns */
.b { display: grid; grid-template: 100px 200px / 400px 800px; }
/* auto: column fills, row fits content */
.c { display: grid; grid-template-rows: 100px auto; grid-template-columns: 200px auto; }
/* fractions */
.d { display: grid; grid-template-rows: 1fr 2fr; grid-template-columns: 1fr 2fr; }
/* limits */
.e { display: grid; grid-template-columns: 200px minmax(400px, 800px); }

.grid-container {
  display: grid;
  grid-template-rows: repeat(2, 200px);
  grid-template-columns: repeat(2, 200px);
  grid-auto-rows: 300px; /* the 5th item gets a new 300px row */
}

solution_code.code:
.parent {
  display: grid;
  grid-template-rows: 1fr 1fr 2fr;
  grid-template-columns: auto 400px minmax(200px, 500px);
  grid-auto-rows: 50px;
}
